function screenIssue(){const o=state.order,oid=visibleOrderId(),dev=visibleDevice();const ok=o.otkPassed&&o.paid>=o.total;return `<div class="section-label">Выдача · заказ №${oid} · ${dev}</div><section class="card"><div class="truth-grid"><div class="truth-line"><label>Ремонт</label><b>✓ Завершён</b></div><div class="truth-line"><label>ОТК</label><b>${o.otkPassed?'✓ Пройден':'✕ Не подтверждён'}</b></div><div class="truth-line"><label>Оплата</label><b>${o.paid>=o.total?'✓ Подтверждена':'✕ Осталось 2 500 ₽'}</b></div><div class="truth-line ${ok?'':'blocker'}"><label>Выдача</label><b>${o.issued?'✓ Выдано клиенту':ok?'Условия выполнены':'Заблокирована'}</b></div></div><div class="inline-actions" style="margin-top:var(--sp)"><button class="small-btn" data-go="documents">Документы</button>${!ok?`<button class="small-btn warn" data-debt="open">Исключение: долг</button>`:''}</div></section>`}
function screenDocuments(){const d=state.documents,o=state.order;const doc=(icon,title,sub,available)=>`<div class="doc ${available?'':'unavailable'}"><span>${ico(icon)}</span><span><b>${title}</b><small>${available?sub:'Будет доступен после соответствующего события'}</small></span><span class="doc-actions">${available?`<button class="icon-btn" data-doc="open" data-doc-title="${title}" data-doc-sub="${sub}">${ico('i-doc')}</button><button class="icon-btn" data-doc="download" data-doc-title="${title}">${ico('i-download')}</button><button class="icon-btn" data-doc="print" data-doc-title="${title}">${ico('i-print')}</button>`:''}</span></div>`;return `<div class="section-label">Документы заказа №125</div><section class="card doc-list">${doc('i-doc','Квитанция приёмки','Доступна после приёмки',true)}${doc('i-doc','Согласование','Подтверждение клиента',state.order.approved)}${doc('i-wrench','Документы ремонта','Работы и использованные детали',state.order.repairDone)}${doc('i-doc','Финальный акт выдачи','Выдача зарегистрирована',state.order.issued)}</section>`}
function screenList(route){const data={clients:[['Иван Иванов','iPhone 13 · заказ №125','client'],['Анна Петрова','iPhone 14','client']],orders:[['№125 · iPhone 13','Нужно согласование','order'],['№124 · iPhone 13','Нужен ОТК','otk']],stock:[['Дисплей iPhone 13','12 шт · 3 200 ₽','part'],['Аккумулятор iPhone 13','7 шт · 1 600 ₽','part']],services:[['Замена дисплея','3 500 ₽ · 60 мин','service'],['Диагностика','1 000 ₽ · 30 мин','service']],suppliers:[['FixParts','1–2 дня · 15 шт','supplier'],['MobileStock','2 дня · 8 шт','supplier']],finance:[['Заказ №125','Осталось 2 500 ₽','payment']],reports:[['Операции сегодня','5 заказов','orders']],history:[['Заказ №125','Диагностика завершена','order']]}[route]||[];return data.map(x=>`<button class="form-row" data-go="${x[2]}"><span><b>${x[0]}</b><label>${x[1]}</label></span><span>›</span></button>`).join('')}
function screenSettings(){return `<div class="section-label">Аккаунт</div><section class="card account-card"><div><b>Иван</b><small>Сотрудник / Мастер</small></div><button class="small-btn" data-auth="logout">Выйти</button></section><div class="section-label">My Workspace</div><section class="card"><div class="workspace-grid">${['graphite','slate','ocean'].map(w=>`<button class="workspace-card ${w} ${state.workspace===w?'active':''}" data-workspace="${w}"><span>${w==='graphite'?'Graphite':w==='slate'?'Slate':'Ocean'}</span></button>`).join('')}</div><div style="height:calc(12px*var(--space-scale))"></div><div class="range-row"><span>Затемнение</span><input type="range" min="0" max="0.18" step="0.02" value="${state.dim}" id="dimRange"><b>${Math.round(state.dim*100)}%</b></div><div style="height:var(--sp)"></div><div class="range-row"><span>Глубина</span><input type="range" min="0.7" max="1.3" step="0.1" value="${state.depth}" id="depthRange"><b>${state.depth.toFixed(1)}</b></div></section><div class="section-label">Масштаб</div><section class="card"><div class="inline-actions"><button class="small-btn" data-set="minus">A−</button><button class="small-btn" data-set="reset">${levels[scaleIndex]}%</button><button class="small-btn" data-set="plus">A+</button><button class="small-btn ghost" data-set="reset">100%</button></div></section>`}
const screens={home:screenHome,search:screenSearch,capture:screenCapture,client:screenClient,device:screenDevice,service:()=>screenSimple('service','Замена дисплея','iPhone 13','service','Замена дисплея','i-tag'),part:()=>screenSimple('part','Дисплей iPhone 13','Совместимость: iPhone 13','part','Дисплей iPhone 13','i-box'),supplier:()=>screenSimple('supplier','FixParts','Поставка 1–2 дня','supplier','FixParts','i-cart'),draft:screenDraft,diagnostics:screenDiagnostics,approval:screenApproval,repair:screenRepair,order:screenOrder,otk:screenOtk,payment:screenPayment,issue:screenIssue,documents:screenDocuments,clients:()=>screenList('clients'),orders:()=>screenList('orders'),stock:()=>screenList('stock'),services:()=>screenList('services'),suppliers:()=>screenList('suppliers'),finance:()=>screenList('finance'),reports:()=>screenList('reports'),history:()=>screenList('history'),settings:screenSettings};
function render(route){return (screens[route]||(()=>`<section class="card">Экран ${route}</section>`))()}
function navigate(route,opts={}){if(!screens[route])return;closeModal();setNextPanel(false);toggleToolbelt(false);settingsBar.classList.remove('open');header.classList.remove('settings-open');const old=pageNode;const oldScroll=old?old.scrollTop:0;if(!opts.back&&!opts.home&&current!==route)historyStack.push({route:current,params:currentParams,scroll:oldScroll});current=route;currentParams=opts.params||{};const n=document.createElement('section');const dir=opts.back?'back':opts.home?'home':'forward';n.className='page enter-'+dir;n.innerHTML=`<div class="wrap">${render(route)}</div>`;stage.appendChild(n);pageNode=n;renderHeader();renderToolbelt();updateNextAction();requestAnimationFrame(()=>{n.classList.remove('enter-'+dir);if(old){old.classList.add('exit-'+dir);setTimeout(()=>old.remove(),260)}});if(opts.restoreScroll)setTimeout(()=>n.scrollTo({top:opts.restoreScroll,behavior:'auto'}),10);bindRouteSpecific()}
function rerender(route=current){if(!pageNode)return navigate(route,{home:route==='home'});const s=pageNode.scrollTop;pageNode.innerHTML=`<div class="wrap">${render(route)}</div>`;renderHeader();renderToolbelt();updateNextAction();bindRouteSpecific();requestAnimationFrame(()=>pageNode.scrollTo({top:s,behavior:'auto'}))}
function goBack(){const h=historyStack.pop();if(!h)return navigate('home',{home:true});navigate(h.route,{back:true,params:h.params,restoreScroll:h.scroll})}
function goHome(){historyStack=[];navigate('home',{home:true});}
function newRepair(source){const preset={client:{client:'Иван Иванов'},device:{client:'Иван Иванов',device:'iPhone 13'},service:{service:'Замена дисплея'},part:{part:'Дисплей iPhone 13',device:'iPhone 13'},supplier:{supplier:'FixParts'},capture:{client:'Иван Иванов',device:'iPhone 13',order:'№125'},order:{client:'Иван Иванов',device:'iPhone 13',order:'№125'},empty:{}}[source]||{};state.context={client:'',device:'',service:'',part:'',supplier:'',order:'',...preset};navigate('draft')}
function fillContext(k){const val={client:'Иван Иванов',device:'iPhone 13',service:'Замена дисплея',part:'Дисплей iPhone 13',supplier:'FixParts'}[k];state.context[k]=val;rerender('draft')}
function act(a){setNextPanel(false);const o=state.order;if(a==='create-repair'){o.diagnosticsDone=false;o.approved=false;o.repairDone=false;o.sentOtk=false;o.otkPassed=false;o.paid=10000;o.payment='partial';o.issued=false;state.documents={intake:true,approval:false,repair:false,final:false};showToast('Ремонт создан · контекст сохранён');setTimeout(()=>navigate('diagnostics'),250)}if(a==='finish-diagnostics'){o.diagnosticsDone=true;showToast('Диагностика подтверждена');setTimeout(()=>navigate('approval'),220)}if(a==='approve'){o.approved=true;state.documents.approval=true;showToast('Согласование подтверждено');setTimeout(()=>navigate('order'),220)}if(a==='finish-repair'){o.repairDone=true;state.documents.repair=true;showToast('Ремонт завершён');setTimeout(()=>navigate('order'),220)}if(a==='send-otk'){o.sentOtk=true;showToast('Передано на ОТК');rerender('order')}if(a==='otk-pass'){o.otkPassed=true;o.otkProblem=false;showToast('ОТК подтверждён · Анна Смирнова');rerender('otk')}if(a==='accept-payment'){o.payment='checking';rerender('payment');setTimeout(()=>{o.paid=o.total;o.payment='confirmed';showToast('Оплата подтверждена');rerender('payment')},900)}if(a==='issue'){o.issued=true;state.documents.final=true;showToast('Выдача зарегистрирована');rerender('issue')}}
function bindRouteSpecific(){if(current==='settings'){const d=$('#dimRange'),dp=$('#depthRange');if(d)d.addEventListener('input',e=>{state.dim=Number(e.target.value);storage.set('aion-v08-dim',String(state.dim));applyWorkspace();const out=e.target.nextElementSibling;if(out)out.textContent=Math.round(state.dim*100)+'%'});if(dp)dp.addEventListener('input',e=>{state.depth=Number(e.target.value);storage.set('aion-v08-depth',String(state.depth));applyWorkspace();const out=e.target.nextElementSibling;if(out)out.textContent=state.depth.toFixed(1)})}}